Import ListNotations.
Open Scope Z_scope.
Set Warnings "-notation-for-abbreviation".
Local Ltac Z.euclidean_division_equations_cleanup ::= idtac.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.

Definition x2_frame (DT WK T nbb wEnd : Z) (p112 p120 p128 p136 p144 : word) : list cell :=
  [C8 (Z_to_bv 64 223338299392); C8 (Z_to_bv 64 (nbb - T)); C8 (Z_to_bv 64 (wEnd - 1)); C8 (Z_to_bv 64 (DT + 52));
   C8 (Z_to_bv 64 (DT + 20)); C8 (Z_to_bv 64 (nbb - wEnd + 1)); C8 (Z_to_bv 64 WK); C8 (Z_to_bv 64 nbb);
   C8 p112; C8 p120; C8 p128; C8 p136; C8 p144; C8 (Z_to_bv 64 (DT + 4))].

Definition x2A_inv (m m1 : fmem) (sp : word) (DT SY WK T nbb wEnd : Z) (js jt : list byte) (sorted : list (option Z))
    (ncells : nat) (dt : list (option deltX2)) : Prop :=
  u8arr psegs m1 (DT + 4) (ox2 jt dt) /\ length dt = ncells
  /\ bytes_at psegs m1 SY (omerge js sorted)
  /\ (exists p112 p120 p128 p136 p144, rw_cells psegs m1 (bv_unsigned sp + 48) (x2_frame DT WK T nbb wEnd p112 p120 p128 p136 p144))
  /\ munch [(DT + 4, DT + 4 + 4 * Z.of_nat ncells); (bv_unsigned sp + 112, bv_unsigned sp + 152)] m m1
  /\ wmono psegs m m1 /\ mem_inv psegs m1.

Section FX.
  Variables (sp gp tp : word) (F : bvmap 5 word) (fc : bv 32).
  Variables (m : fmem) (DT SY WK T nbb wEnd : Z) (sorted : list (option Z)) (js jt : list byte) (ncells : nat)
    (rs0 rv : list Z).
  Variable POST : machine_state -> Prop.
  Notation SP := (bv_unsigned sp).
  Hypothesis HJT : length jt = (4 * ncells)%nat.
  Hypothesis HJS : length js = length sorted.
  Hypothesis HLS : length sorted = 256%nat.
  Hypothesis HSYR : forall i v, nth i sorted None = Some v -> 0 <= v < 256.
  Hypothesis HDT : 0 < DT /\ DT + 4 + 4 * Z.of_nat ncells <= 2^47.
  Hypothesis HSYE : SY = WK + 736.
